import { CheckoutForm, checkoutErrorMessage, createCheckoutForm } from './checkout-form';

function filledForm(): CheckoutForm {
  const form = createCheckoutForm(undefined);
  form.patchValue({
    firstName: 'Anna',
    lastName: 'Kowalska',
    email: 'anna@example.com',
    confirmEmail: 'anna@example.com',
    phone: '',
    terms: true,
  });
  return form;
}

describe('checkout form rules', () => {
  it('is valid when every required field is filled and the phone is empty', () => {
    expect(filledForm().valid).toBe(true);
  });

  it('shows no message before a field has been left', () => {
    const form = createCheckoutForm(undefined);
    expect(checkoutErrorMessage(form, 'firstName')).toBeNull();
    expect(checkoutErrorMessage(form, 'terms')).toBeNull();
  });

  it('requires first and last name, at least 2 characters each', () => {
    const form = createCheckoutForm(undefined);
    form.controls.firstName.markAsTouched();
    expect(checkoutErrorMessage(form, 'firstName')).toBe('First name is required');

    form.controls.firstName.setValue('A');
    expect(checkoutErrorMessage(form, 'firstName')).toBe('First name must be at least 2 characters');

    form.controls.firstName.setValue('Al');
    expect(checkoutErrorMessage(form, 'firstName')).toBeNull();

    form.controls.lastName.markAsTouched();
    expect(checkoutErrorMessage(form, 'lastName')).toBe('Last name is required');
    form.controls.lastName.setValue('K');
    expect(checkoutErrorMessage(form, 'lastName')).toBe('Last name must be at least 2 characters');
  });

  it('accepts only valid email addresses', () => {
    const form = createCheckoutForm(undefined);
    form.controls.email.markAsTouched();
    expect(checkoutErrorMessage(form, 'email')).toBe('Email is required');

    for (const invalid of ['not-an-email', 'a@b', 'a@.com', 'a@b.', ' anna@example.com', 'a b@c.com']) {
      form.controls.email.setValue(invalid);
      expect(checkoutErrorMessage(form, 'email')).toBe('Enter a valid email address');
    }

    form.controls.email.setValue('anna@example.com');
    expect(checkoutErrorMessage(form, 'email')).toBeNull();
  });

  it('requires the confirmation to match Email as typed', () => {
    const form = filledForm();
    form.controls.confirmEmail.setValue('');
    form.controls.confirmEmail.markAsTouched();
    expect(checkoutErrorMessage(form, 'confirmEmail')).toBe('Confirm email is required');

    form.controls.confirmEmail.setValue('anna@example.org');
    expect(checkoutErrorMessage(form, 'confirmEmail')).toBe('Email addresses do not match');
    expect(form.valid).toBe(false);
  });

  it('re-checks the confirmation when Email changes', () => {
    const form = filledForm();
    form.controls.email.setValue('other@example.com');
    expect(form.controls.confirmEmail.valid).toBe(false);

    form.controls.confirmEmail.setValue('other@example.com');
    expect(form.controls.confirmEmail.valid).toBe(true);
  });

  it('checks a restored confirmation against the restored Email', () => {
    const form = createCheckoutForm({
      firstName: 'Anna',
      lastName: 'Kowalska',
      email: 'anna@example.com',
      confirmEmail: 'anna@example.com',
      phone: '',
      terms: true,
    });
    expect(form.valid).toBe(true);
  });

  it('treats an empty phone as valid and otherwise requires exactly 9 digits', () => {
    const form = filledForm();
    form.controls.phone.markAsTouched();
    expect(checkoutErrorMessage(form, 'phone')).toBeNull();

    for (const invalid of ['12345678', '1234567890', '12345678a', '123 45678']) {
      form.controls.phone.setValue(invalid);
      expect(checkoutErrorMessage(form, 'phone')).toBe('Phone number must be exactly 9 digits');
    }

    form.controls.phone.setValue('123456789');
    expect(checkoutErrorMessage(form, 'phone')).toBeNull();
  });

  it('requires the terms checkbox once it has been toggled', () => {
    const form = filledForm();
    form.controls.terms.setValue(false);
    form.controls.terms.markAsTouched();
    expect(checkoutErrorMessage(form, 'terms')).toBe('You must accept the terms and conditions');
    expect(form.valid).toBe(false);
  });

  it('restores the given values', () => {
    const form = createCheckoutForm({
      firstName: 'Anna',
      lastName: 'K',
      email: 'a',
      confirmEmail: 'b',
      phone: '123',
      terms: true,
    });
    expect(form.getRawValue()).toEqual({
      firstName: 'Anna',
      lastName: 'K',
      email: 'a',
      confirmEmail: 'b',
      phone: '123',
      terms: true,
    });
  });
});

import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { Router, provideRouter } from '@angular/router';
import { BookingService } from '../booking';
import { ToastService } from '../toast';
import { Checkout } from './checkout';

const BOOKING = { screeningId: 1, seats: ['R7C12', 'R15C1', 'R15C2'] };

function input(fixture: ComponentFixture<Checkout>, testId: string): HTMLInputElement {
  return fixture.nativeElement.querySelector(`[data-testid="${testId}"]`) as HTMLInputElement;
}

function text(fixture: ComponentFixture<Checkout>, testId: string): string | null {
  return (fixture.nativeElement.querySelector(`[data-testid="${testId}"]`) as HTMLElement | null)?.textContent?.trim() ?? null;
}

/** Types a value into a field and leaves it, as a customer would. */
function type(fixture: ComponentFixture<Checkout>, testId: string, value: string): void {
  const element = input(fixture, testId);
  element.value = value;
  element.dispatchEvent(new Event('input'));
  element.dispatchEvent(new Event('blur'));
  fixture.detectChanges();
}

function fillValidForm(fixture: ComponentFixture<Checkout>): void {
  type(fixture, 'first-name-input', 'Anna');
  type(fixture, 'last-name-input', 'Kowalska');
  type(fixture, 'email-input', 'anna.kowalska@example.com');
  type(fixture, 'confirm-email-input', 'anna.kowalska@example.com');
  input(fixture, 'terms-checkbox').querySelector('input')?.click();
  fixture.detectChanges();
}

function pay(fixture: ComponentFixture<Checkout>): void {
  (fixture.nativeElement.querySelector('[data-testid="pay-button"]') as HTMLButtonElement).click();
  fixture.detectChanges();
}

describe('Checkout', () => {
  let fixture: ComponentFixture<Checkout>;
  let httpMock: HttpTestingController;
  let toast: ToastService;
  let router: Router;

  beforeEach(async () => {
    sessionStorage.clear();
    sessionStorage.setItem('cinescope.booking', JSON.stringify(BOOKING));
    await TestBed.configureTestingModule({
      imports: [Checkout],
      providers: [
        provideHttpClient(),
        provideHttpClientTesting(),
        provideRouter([{ path: 'confirmation', children: [] }]),
      ],
    }).compileComponents();

    httpMock = TestBed.inject(HttpTestingController);
    toast = TestBed.inject(ToastService);
    router = TestBed.inject(Router);
    fixture = TestBed.createComponent(Checkout);
    fixture.detectChanges();
  });

  afterEach(() => {
    httpMock.verify();
    sessionStorage.clear();
  });

  it('shows the title, the total and the labels with asterisks on required fields', () => {
    expect(text(fixture, 'checkout-title')).toBe('Your details');
    expect(text(fixture, 'pay-button')).toBe('Pay 96.00 PLN');
    expect(text(fixture, 'first-name-label')).toBe('First name *');
    expect(text(fixture, 'phone-label')).toBe('Phone number');
  });

  it('marks every field and shows the toast on an invalid form, without sending a request', () => {
    const show = spyOn(toast, 'show');
    pay(fixture);

    expect(text(fixture, 'first-name-error')).toBe('First name is required');
    expect(text(fixture, 'email-error')).toBe('Email is required');
    expect(text(fixture, 'terms-error')).toBe('You must accept the terms and conditions');
    expect(show).toHaveBeenCalledWith('The form contains errors');
    httpMock.expectNone('http://localhost:3000/reservations');
  });

  it('shows a message once a field has been left', () => {
    type(fixture, 'first-name-input', 'A');
    expect(text(fixture, 'first-name-error')).toBe('First name must be at least 2 characters');
    expect(text(fixture, 'last-name-error')).toBeNull();
  });

  it('sends the reservation, then marks the booking paid and opens the confirmation', async () => {
    fillValidForm(fixture);
    pay(fixture);

    const request = httpMock.expectOne('http://localhost:3000/reservations');
    expect(request.request.method).toBe('POST');
    expect(request.request.body).toEqual({
      screeningId: 1,
      seats: ['R7C12', 'R15C1', 'R15C2'],
      customer: {
        firstName: 'Anna',
        lastName: 'Kowalska',
        email: 'anna.kowalska@example.com',
        phone: '',
      },
      totalPrice: 96,
    });
    expect(text(fixture, 'pay-button')).toBe('Processing…');
    expect(input(fixture, 'first-name-input').value).toBe('Anna');

    const navigate = spyOn(router, 'navigateByUrl').and.resolveTo(true);
    request.flush({ id: 1, ...request.request.body }, { status: 201, statusText: 'Created' });
    fixture.detectChanges();

    expect(JSON.parse(sessionStorage.getItem('cinescope.booking') ?? '{}').paidEmail).toBe(
      'anna.kowalska@example.com',
    );
    expect(navigate).toHaveBeenCalledWith('/confirmation');
  });

  it('keeps the form and shows the toast when the payment fails', () => {
    const show = spyOn(toast, 'show');
    fillValidForm(fixture);
    pay(fixture);

    httpMock
      .expectOne('http://localhost:3000/reservations')
      .flush('error', { status: 500, statusText: 'Server Error' });
    fixture.detectChanges();

    expect(show).toHaveBeenCalledWith('Payment failed. Please try again.');
    expect(text(fixture, 'pay-button')).toBe('Pay 96.00 PLN');
    expect((fixture.nativeElement.querySelector('[data-testid="pay-button"]') as HTMLButtonElement).disabled).toBe(
      false,
    );
    expect(input(fixture, 'email-input').value).toBe('anna.kowalska@example.com');
  });

  it('keeps the typed values in the booking', () => {
    type(fixture, 'first-name-input', 'Anna');
    const stored = JSON.parse(sessionStorage.getItem('cinescope.booking') ?? '{}');
    expect(stored.checkout.firstName).toBe('Anna');
    expect(stored.seats).toEqual(BOOKING.seats);
  });

  it('restores the values of the booking', () => {
    sessionStorage.setItem(
      'cinescope.booking',
      JSON.stringify({ ...BOOKING, checkout: { firstName: 'Ola', lastName: 'Nowak', email: 'o@example.com', confirmEmail: 'o@example.com', phone: '', terms: true } }),
    );
    const restored = TestBed.createComponent(Checkout);
    restored.detectChanges();
    expect(input(restored, 'first-name-input').value).toBe('Ola');
    expect(text(restored, 'first-name-error')).toBeNull();
    expect(TestBed.inject(BookingService).current()?.paidEmail).toBeUndefined();
  });
});

